```ts
type Kind = "created" | "updated";

interface EventV1 {
  version: 1;
  id: string;
  occurredAt: string;
  kind: Kind;
}

interface EventV2 {
  version: 2;
  id: string;
  occurredAt: string;
  kind: Kind;
  actorId?: string;
}

